#!/usr/bin/env node
/**
 * c-wasm-bolton S3: client-vs-server cell dep-closure parity test.
 *
 * Authority: tests/fixtures/cell-parity.json (generated by the server's
 * refs_of + dependency_closure — regenerate with the python snippet in
 * the fixture header when the server semantics change).
 *
 * Order-independence: cells.py documents "ANY deterministic order is
 * fine — the translator resolves order"; closures compare as SETS, with
 * order differences reported as informational.
 *
 * Usage: node scripts/cell-parity.mjs   (after esbuild-transpiling
 * src/lib/{cells,cell-deps}.ts to a temp dir — the script does it).
 */
import { execSync } from "node:child_process";
import { mkdtempSync, readFileSync, cpSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const tmp = mkdtempSync(join(tmpdir(), "cell-parity-"));
execSync(
  `./node_modules/.bin/esbuild src/lib/cells.ts src/lib/cell-deps.ts --format=esm --outdir=${tmp}`,
  { stdio: "pipe" },
);
const depPath = join(tmp, "cell-deps.js");
let depSrc = readFileSync(depPath, "utf8");
depSrc = depSrc.replace(/from "\.\/cells"/g, 'from "./cells.js"');
writeFileSync(depPath, depSrc);
cpSync("tests/fixtures/cell-parity.json", join(tmp, "fixture.json"));
cpSync(new URL(import.meta.url).pathname.replace(/[^/]*$/, ""), tmp, { recursive: true });
const { buildCellGraph, dependencyClosure } = await import(
  `file://${join(tmp, "cell-deps.js")}`
);
const fixture = JSON.parse(readFileSync(join(tmp, "fixture.json"), "utf8"));

let fails = 0;
let checks = 0;
for (const [libName, lib] of Object.entries(fixture)) {
  const g = buildCellGraph(lib.text);
  for (const [target, expected] of Object.entries(lib.closures)) {
    const got = dependencyClosure(target, g.refs, new Set(g.order));
    checks++;
    const ok = got.slice().sort().join(",") === expected.slice().sort().join(",");
    if (!ok) {
      fails++;
      console.error("SET-MISMATCH", libName, target, "server:", JSON.stringify(expected), "client:", JSON.stringify(got));
    } else if (JSON.stringify(got) !== JSON.stringify(expected)) {
      console.log("order-differs (spec-OK):", libName, target);
    }
  }
}
console.log(fails === 0 ? `PARITY OK (${checks} closures)` : `${fails} FAILS / ${checks}`);
process.exit(fails === 0 ? 0 : 1);
